def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_c_total = sum(1 for _, o in history if o == 'C')
    if opp_c_total == 0:
        return 'D'
    coop_rate = opp_c_total / n

    rec_len = min(10, n)
    opp_c_recent = sum(1 for _, o in history[-rec_len:] if o == 'C')
    recent_rate = opp_c_recent / rec_len
    if opp_c_recent == 0:
        return 'D'

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    after_d_n = 0
    after_d_c = 0
    olive_n = 0
    olive_s = 0
    for i in range(1, n):
        prev_my = history[i - 1][0]
        prev_opp = history[i - 1][1]
        cur_opp = history[i][1]
        if prev_my == 'D':
            after_d_n += 1
            if cur_opp == 'C':
                after_d_c += 1
        if prev_my == 'C' and prev_opp == 'D':
            olive_n += 1
            if cur_opp == 'C':
                olive_s += 1

    after_d_rate = after_d_c / after_d_n if after_d_n else 0.0
    olive_rate = olive_s / olive_n if olive_n else 1.0
    remaining = 100 - n

    if coop_rate < 0.45 or recent_rate < 0.30:
        return 'D'

    if opp_last == 'D':
        if my_last == 'D' and opp_d_streak <= 2 and coop_rate > 0.55 and recent_rate > 0.40:
            if olive_n >= 2 and olive_rate < 0.45:
                return 'D'
            if remaining <= 4:
                return 'D'
            if opp_d_streak == 1:
                return 'C'
            if remaining > 25:
                return 'C'
            return 'C' if rng.random() < 0.50 else 'D'
        return 'D'

    if after_d_n >= 2 and after_d_rate >= 0.65 and coop_rate > 0.55:
        if my_d_streak <= 4 or after_d_rate >= 0.85:
            return 'D'

    if after_d_n >= 1 and after_d_rate >= 0.90 and my_d_streak <= 2 and coop_rate > 0.60:
        return 'D'

    if remaining <= 8 and after_d_n >= 1 and after_d_rate >= 0.50 and opp_c_streak >= 3:
        return 'D'

    return 'C'
